#include "../Source/Expansion/InstrumentModel.h"
#include "../Source/Expansion/MPEExpression.h"
#include <cassert>
#include <cmath>
#include <iostream>
using namespace sampler;
static SampleZone z(const char* id,int kl,int kh,int vl,int vh,int rr=0){SampleZone s;s.id=id;s.sample={"sample-"+s.id,"/samples/"+s.id+".wav",48000,2,48000};s.keyLow=std::uint8_t(kl);s.keyHigh=std::uint8_t(kh);s.velocityLow=std::uint8_t(vl);s.velocityHigh=std::uint8_t(vh);s.rootKey=std::uint8_t((kl+kh)/2);s.roundRobinGroup=std::uint8_t(rr);return s;}
int main(){InstrumentModel m;assert(m.addZone(z("soft",48,72,1,63)));assert(m.addZone(z("hard",48,72,64,127)));auto a=m.select(60,40),b=m.select(60,100);assert(a.size()==1&&a[0].zone->id=="soft");assert(b.size()==1&&b[0].zone->id=="hard");assert(!m.addZone(z("bad",72,48,1,127)));assert(m.validate());InstrumentModel rr;assert(rr.addZone(z("always",0,127,1,127)));assert(rr.addZone(z("rr-a",0,127,1,127,1)));assert(rr.addZone(z("rr-b",0,127,1,127,1)));auto r1=rr.select(60,100),r2=rr.select(60,100);assert(r1.size()==2&&r2.size()==2&&r1[1].zone->id!=r2[1].zone->id);MPEExpression mpe({MPEZoneConfig::Layout::Lower,15,48});assert(mpe.isMemberChannel(2)&&!mpe.isMemberChannel(1));mpe.process({MPEEvent::Type::PitchBend,2,60,0,16383});mpe.process({MPEEvent::Type::ChannelPressure,2,0,0,100});mpe.process({MPEEvent::Type::ControlChange,2,0,74,80});mpe.process({MPEEvent::Type::PolyPressure,2,60,0,64});auto e=mpe.forChannel(2);assert(e.pitchBendSemitones>47.9f);assert(std::abs(e.pressure-100.0f/127)<0.0001f);assert(std::abs(e.slide-80.0f/127)<0.0001f);assert(std::abs(mpe.perNotePressure(2,60)-64.0f/127)<0.0001f);mpe.process({MPEEvent::Type::ControlChange,2,0,64,0});assert(mpe.forChannel(2).sustain==0);mpe.reset();assert(mpe.forChannel(2).pressure==0);std::cout<<"Sampler Expansion tests passed\n";}
